function cat = plural(n)
  if (n == 1)
    cat = "one";
  elseif (n == 2)
    cat = "two";
  else
    mod100 = mod(n, 100);
    if (n == 0 || (mod100 >= 3 && mod100 <= 10))
      cat = "few";
    elseif (mod100 >= 11 && mod100 <= 19)
      cat = "many";
    else
